@startuml

class Company {
}

class Employee {
  + Name : string
  + SocialSecurityNumber : string
}

class Planner extends Employee {
  + Username : string
  + Password : string
}

class AdministrativeStaff extends Employee {
  + Username : string
  + Password : string
  + FieldOfActivity : string
}

class Driver extends Employee {
}

class Customer {
  + Name : string
  + BillingAddress : string
}

class PartnerCompany {
  + Name : string
  + Address : string
}

class Vehicle {
  + LicensePlateNumber : string
  + Mileage : int
}

class RefrigeratedTruck extends Vehicle {}

class SmallVan extends Vehicle {}

class LoadingPlatform extends Vehicle {}

class BoxTruck extends Vehicle {}

class RepairShop {
  + Name : string
  + Address : string
}

class Repair {
  + Duration : string
  + Cost : float
}

class Order {
  + PackageSize : string
  + PickupAddress : string
  + DeliveryAddress : string
  + Comment : string
  + StartTime : datetime
  + FinishTime : datetime
}

Company "1" -- "0..*" Employee
Company "1" -- "0..*" Customer
Company "1" -- "0..*" Vehicle
Company "1" -- "0..*" Order

Employee "0..*" -- "0..*" Order : assigns
Driver "1" -- "0..*" Order : completes
Vehicle "1" -- "0..*" Order : is used for
Customer "1" -- "0..*" Order : is client
AdministrativeStaff "0..*" -- "0..*" Order : places
PartnerCompany "0..*" -- "0..*" Order : places

Vehicle "0..*" -- "0..*" Repair : undergoes
Repair "0..*" -- "1" Employee : is taken by
Repair "0..*" -- "1" RepairShop : occurs at

@enduml

